def init_db(database_url: str = "sqlite:///shoply.db"):
    global _engine
    _engine = create_engine(database_url, future=True)
    SessionLocal.configure(bind=_engine)
    Base.metadata.create_all(_engine)
    return _engine

def get_engine():
    return _engine

def get_session():
    return SessionLocal()

@orders_bp.route("/by-status", methods=["GET"])
@require_role("manager")
def orders_by_status():
    """List orders filtered by status."""
    status = request.args.get("status", "pending")
    session = get_session()
    rows = session.execute(
        text("SELECT id, user_id, status, total FROM orders WHERE status = :status"),
        {"status": status},
    )
    return jsonify([dict(r._mapping) for r in rows])

def is_owner_or_admin(user: User, owner_id: int) -> bool:
    """Ownership check used for per-object access (orders, profiles)."""
    return user.id == owner_id or user.role == "admin"

